pragma solidity ^0.8.20;

contract CertificateVerification {

    struct Certificate {
        string certificateId;
        string studentName;
        string courseName;
        string issueDate;
        address issuer;
        bool exists;
    }

    mapping(string => Certificate) private certificates;
    string[] private certificateIds;

    event CertificateAdded(
        string certificateId,
        string studentName,
        string courseName,
        string issueDate,
        address issuer
    );

    function addCertificate(
        string memory _certificateId,
        string memory _studentName,
        string memory _courseName,
        string memory _issueDate
    ) public {

        require(bytes(_certificateId).length > 0, "Certificate ID is required");
        require(bytes(_studentName).length > 0, "Student name is required");
        require(bytes(_courseName).length > 0, "Course name is required");
        require(bytes(_issueDate).length > 0, "Issue date is required");

        require(
            !certificates[_certificateId].exists,
            "Certificate ID already exists"
        );

        certificates[_certificateId] = Certificate(
            _certificateId,
            _studentName,
            _courseName,
            _issueDate,
            msg.sender,
            true
        );

        certificateIds.push(_certificateId);

        emit CertificateAdded(
            _certificateId,
            _studentName,
            _courseName,
            _issueDate,
            msg.sender
        );
    }

    function getCertificate(
        string memory _certificateId
    )
        public
        view
        returns (
            string memory,
            string memory,
            string memory,
            string memory,
            address,
            bool
        )
    {
        require(
            certificates[_certificateId].exists,
            "Certificate not found"
        );

        Certificate memory cert = certificates[_certificateId];

        return (
            cert.certificateId,
            cert.studentName,
            cert.courseName,
            cert.issueDate,
            cert.issuer,
            cert.exists
        );
    }

    function certificateExists(
        string memory _certificateId
    ) public view returns (bool) {
        return certificates[_certificateId].exists;
    }

    function getCertificateCount()
        public
        view
        returns (uint256)
    {
        return certificateIds.length;
    }
}
